function getTimeStem(dayMaster, timeHour):
  earthlyBranch = TIME_BRANCHES[Math.floor(timeHour / 2)] // 2時間単位のグループ
  dayGroup = DAY_MASTER_GROUPS[dayMaster] // 日干グループ分類
  row = MATRIX.rows[Math.floor(timeHour / 2)]
  heavenlyStem = row[dayGroup]
  return {stem: heavenlyStem, branch: earthlyBranch}
